    fire(DeadlineNoticeKind.halfBudget, total > 0 && remaining <= total ~/ 2);
    fire(DeadlineNoticeKind.wrapUp, remaining <= ladder.wrapUpSteerMs);
    fire(DeadlineNoticeKind.finalAnswer, remaining <= ladder.finalAnswerMs);
    return out;
  }
}

